1	// The Deep Field sky: every person's card is a unique patch of space,
2	// minted deterministically from their identity. Same person, same sky,
3	// forever. Pure and dependency-free so it stays trivially testable.
4	
5	export type SkyStar = {
6	  x: number;
7	  y: number;
8	  r: number;
9	  hi: number; // resting opacity
10	  lo: number; // twinkle-low opacity
11	  dur: number; // twinkle duration seconds
12	  delay: number;
13	  rvd: number; // 0..1 reveal stagger seed: when this star ignites
14	  // Minors only: a seeded few keep their own twinkle; the rest render static
15	  // under a shared group shimmer, so the sky animates ~30 nodes, not ~150.
16	  featured?: boolean;
17	};
